/* ---------------- textos con valores ---------------- */
const MESES = { ene:"Jan", feb:"Feb", mar:"Mar", abr:"Apr", may:"May", jun:"Jun", jul:"Jul", ago:"Aug", set:"Sep", sep:"Sep", sept:"Sep", oct:"Oct", nov:"Nov", dic:"Dec" };
const PLANES = { "Prueba":"Trial", "Profesional":"Professional", "Equipo":"Team", "Empresa":"Enterprise", "Gratuito":"Free", "Prueba vencida":"Trial expired" };
const plan = (x, t) => PLANES[x] || (/^Prueba \(hasta el (.+)\)$/.test(x) ? x.replace(/^Prueba \(hasta el (.+)\)$/, "Trial (until $1)") : t(x));
// tipos de tablero en los nombres de los documentos («del tablero de fuerza y control», «de los tableros de fuerza y de distribución»)
const TIPO_TB = { "fuerza y control":"power and control", "fuerza":"power", "distribución":"distribution", "control":"control" };
const listaEn = a => a.length < 2 ? (a[0] || "") : a.slice(0, -1).join(", ") + " and " + a[a.length - 1];
const tiposTb = s => { const p = s.split(/,\s*(?:de\s+)?|\s+y\s+de\s+/).map(x => x.trim()); return p.every(x => TIPO_TB[x]) ? listaEn(p.map(x => TIPO_TB[x])) : null; };
const may = s => s ? s[0].toUpperCase() + s.slice(1) : s;
const DIAGRAMA = { unifilar:"single-line diagram", multifilar:"wiring diagram", "mecánico":"mechanical drawing" };
const yEn = s => String(s).replace(/ y /g, " and ");
const oEn = s => String(s).replace(/ o -$/, " or -").replace(/ o /g, " or ");

// listas «a · b · c» que se traducen por partes: solo con textos del catálogo (no datos del usuario como «Cliente · Planta»)
const PARTES = new Set(["Electricidad", "Instrumentación & Control", "I&C", "General", "Transversal (ambas disciplinas)", "Excel", "Word", "DXF (AutoCAD)",
  "Datos de proceso", "conceptual", "básica", "detalle", "de detalle", "Ingeniería conceptual", "Ingeniería básica", "Ingeniería de detalle"]);

export const REGLAS = [
  [/ · /, (m, t) => { const p = m.input.split(" · "); return p.every(x => PARTES.has(x)) ? p.map(t).join(" · ") : null; }],
  [/, /, (m, t) => { const p = m.input.split(", "); return p.length > 1 && p.every(x => PARTES.has(x)) ? p.map(t).join(", ") : null; }],
  [/^(.+) · (Fabricante a definir|p\.ej\. (.+))$/, (m, t) => `${t(m[1])} · ${m[3] ? "e.g. " + m[3] : "Manufacturer to be defined"}`],
  [/^(.+) · (\d+(?:[.,]\d+)?) m³\/h$/, (m, t) => { const r = t(m[1]); return r !== m[1] ? `${r} · ${m[2]} m³/h` : null; }],
  [/^Módulos (.+):$/, m => `${m[1]} modules:`],
  // selector de tablero «TF-001 — Tablero de fuerza» (con el nombre por defecto del tablero)
  [/^(.+) — (Tablero de (?:distribución|fuerza|fuerza y control|control))$/, (m, t) => `${m[1]} — ${t(m[2])}`],
  [/^(\d+) planos, uno por tablero:$/, m => `${m[1]} drawings, one per panel:`],
  [/^Un plano por tablero \((\d+)\)\. Descarga uno o todos:$/, m => `One drawing per panel (${m[1]}). Download one or all:`],
  [/^(.+ V(?:ac|dc)) · ([13])F · (.+ Hz)$/, m => `${m[1]} · ${m[2]}Ph · ${m[3]}`],
  [/^Versión (.+)$/, m => `Version ${m[1]}`],
  [/^(\d+) registro\(s\)$/, m => `${m[1]} record(s)`],
  [/^(\d+) registro\(s\) · los campos Ítem(, Slot, CH y Terminales)? se asignan automáticamente$/, m => `${m[1]} record(s) · the Item${m[2] ? ", Slot, CH and Terminals" : ""} field${m[2] ? "s are" : " is"} assigned automatically`],
  [/^(\d+) documentos?$/, m => `${m[1]} document${m[1] === "1" ? "" : "s"}`],
  [/^(\d+)\/(\d+) emitidos$/, m => `${m[1]}/${m[2]} issued`],
  [/^(\d+) seleccionado\(s\)(?: · (.+))?$/, (m, t) => `${m[1]} selected${m[2] ? " · " + t(m[2]) : ""}`],
  [/^Proyecto creado con (\d+) documentos: abre cada uno para ingresar sus datos$/, m => `Project created with ${m[1]} documents: open each one to enter its data`],
  [/^(.+) Vac · (.+) Hz · control (.+) · (\d+) tablero\(s\)$/, m => `${m[1]} Vac · ${m[2]} Hz · control ${yEn(m[3])} · ${m[4]} panel(s)`],
  [/^(\d+(?:[.,]\d+)?) V(ac|dc) y (\d+(?:[.,]\d+)?) V(ac|dc)$/, m => `${m[1]} V${m[2]} and ${m[3]} V${m[4]}`],
  [/^control (.+ V(?:ac|dc)) y (.+ V(?:ac|dc))$/, m => `control ${m[1]} and ${m[2]}`],
  [/^(\d+) documentos · (\d+) cargas · (\d+) instrumentos$/, m => `${m[1]} documents · ${m[2]} loads · ${m[3]} instruments`],
  [/^(\d+) de (\d+) documentos emitidos$/, m => `${m[1]} of ${m[2]} documents issued`],
  [/^Se eliminará «(.+)» con todos sus datos\.$/, m => `“${m[1]}” will be deleted with all its data.`],
  [/^(\d{1,2})(?: de)? (ene|feb|mar|abr|may|jun|jul|ago|sept?|oct|nov|dic)\.?(?: de)? (\d{4})$/i, m => `${m[1]} ${MESES[m[2].toLowerCase()]} ${m[3]}`],
  [/^(\d+(?:[.,]\d+)?) m s\.n\.m\.$/, m => `${m[1]} m a.s.l.`],
  // plan
  [/^Prueba \(hasta el (.+)\)$/, m => `Trial (until ${m[1]})`],
  [/^Plan (.+) activado$/, (m, t) => `${plan(m[1], t)} plan activated`],
  [/^Activar (.+)$/, (m, t) => `Activate ${plan(m[1], t)}`],
  [/^Probar (\d+) días gratis$/, m => `Try ${m[1]} days free`],
  [/^«(.+)» \((.+)\) es parte del plan Profesional\. Tu plan actual:$/, (m, t) => `“${t(m[1])}” (${m[2]}) is part of the Professional plan. Your current plan:`],
  // nombres de documentos según los tableros del proyecto
  [/^Diagrama (unifilar|multifilar|mecánico) (del tablero|de los tableros) de (.+)$/, m => { const x = tiposTb(m[3]); return x ? `${may(x)} panel${m[2] === "del tablero" ? "" : "s"} ${DIAGRAMA[m[1]]}` : null; }],
  [/^Cargas de los tableros de (.+)$/, m => { const x = tiposTb(m[1]); return x ? `${may(x)} panel loads` : null; }],
  [/^Distribución de potencia, barras, alimentadores y protecciones de cada tablero de (.+) \(simbología NEMA \/ ANSI\)\.$/, m => { const x = tiposTb(m[1].replace(/ \/ distribución$/, ", de distribución")); return x ? `Power distribution, buses, feeders and protective devices of each ${x} panel (NEMA / ANSI symbols).` : null; }],
  // documento
  [/^No se pudo calcular la vista previa: (.*)$/, m => `Could not calculate the preview: ${m[1]}`],
  [/^(\d+) hoja\(s\) \+ carátula \+ índice$/, m => `${m[1]} sheet(s) + cover sheet + index`],
  [/^(\d+) de (\d+)$/, m => `${m[1]} of ${m[2]}`],
  [/^(\d+) lámina\(s\) A1 · (\d+) entidades · capas: (\d+)$/, m => `${m[1]} A1 sheet(s) · ${m[2]} entities · layers: ${m[3]}`],
  [/^Gabinete (.+) mm · (\d+) sección\(es\) · (\d+) equipos · ventilación (.+)$/, (m, t) => `Enclosure ${m[1]} mm · ${m[2]} section(s) · ${m[3]} devices · ${t(m[4])} ventilation`],
  [/^No se pudo armar la vista 3D: (.*)$/, m => `Could not build the 3D view: ${m[1]}`],
  [/^Página (\d+) de (\d+)$/, m => `Page ${m[1]} of ${m[2]}`],
  [/^No se pudo preparar la vista del PDF: (.*)$/, m => `Could not prepare the PDF view: ${m[1]}`],
  [/^Documento generado: (.+)$/, (m, t) => `Document generated: ${t(m[1])}`],
  [/^No se pudo generar: (.*)$/, m => `Could not generate: ${m[1]}`],
  [/^Descargar (.+)$/, (m, t) => `Download ${t(m[1])}`],
  // editores
  [/^(\d+) fila\(s\) importadas$/, m => `${m[1]} row(s) imported`],
  [/^Reserva (\d+(?:[.,]\d+)?) % · canales por módulo según la configuración del tablero de control$/, m => `Spare ${m[1]} % · channels per module according to the control panel configuration`],
  [/^Ej\.?: (.+)$/, (m, t) => `E.g. ${oEn(t(m[1]))}`],
  [/^(.+) \(por defecto\)$/, m => `${m[1]} (default)`],
  [/^y (\d+) más$/, m => `and ${m[1]} more`],
  [/^Configuración de (.+) aplicada a (\d+) tablero\(s\)$/, m => `Configuration of ${m[1]} applied to ${m[2]} panel(s)`],
  [/^Aplicar a los (\d+) tableros de control$/, m => `Apply to the ${m[1]} control panels`],
  [/^(.+) no tiene entradas de 120 Vac: las entradas digitales quedan en 24 Vdc$/, m => `${m[1]} has no 120 Vac inputs: the digital inputs are set to 24 Vdc`],
  [/^Elegido: (mural|autosoportado)$/, m => `Selected: ${m[1] === "mural" ? "wall-mounted" : "floor-standing"}`],
  [/^Criterio del proyecto: (.+) %$/, m => `Project criterion: ${m[1]} %`],
  [/^Automático: (.+)$/, m => `Automatic: ${m[1]}`],
  [/^Balance térmico: (.+)$/, (m, t) => `Thermal balance: ${t(m[1])}`],
  [/^Se dibuja: (.+)$/, (m, t) => `Drawn: ${t(m[1])}`],
  [/^El tablero (.+) aún no tiene cargas: agrégalas en el listado de cargas para armar el arreglo\.$/, m => `Panel ${m[1]} has no loads yet: add them in the load list to build the layout.`],
  [/^Dimensiones referenciales de catálogo: verificar con el plano dimensional del código exacto antes de fabricar\. Pídele cambios a Copito, por ejemplo: (.*)$/, m => `Reference catalog dimensions: check against the dimensional drawing of the exact part number before manufacturing. Ask Copito for changes (in Spanish), for example: ${m[1]}`],
  [/^CPU en el slot (\d+)(?:, fuente en el (\d+))?( \(doble ancho: 0-1\))?$/, m => `CPU in slot ${m[1]}${m[2] ? `, power supply in ${m[2]}` : ""}${m[3] ? " (double width: 0-1)" : ""}`],
  [/^Circuitos editados de (.+)\.$/, m => `Edited circuits of ${m[1]}.`],
  [/^Etapa de control de (.+) editada; estas cargas dimensionan el multifilar del tablero\.$/, m => `Control section of ${m[1]} edited; these loads size the panel wiring diagram.`],
  [/^(\d+) señales generadas$/, m => `${m[1]} signals generated`],
  [/^Valores típicos para el tipo (.+)$/, m => `Typical values for type ${m[1]}`],
  [/^(\d+) equipo\(s\) importados$/, m => `${m[1]} equipment item(s) imported`],
  [/^(\d+) instrumento\(s\) agregados; listado I\/O actualizado$/, m => `${m[1]} instrument(s) added; I/O list updated`],
  [/^(\d+) tablero\(s\) ubicados en su centro de carga$/, m => `${m[1]} panel(s) placed at their load center`],
  [/^Sin equipos: completa primero (las cargas y tableros|el listado de instrumentos)\.$/, m => `No equipment: first complete ${m[1] === "las cargas y tableros" ? "the loads and panels" : "the instrument list"}.`],
  [/^Agregado a «(.+)»$/, (m, t) => `Added to “${t(m[1])}”`],
  [/^Actualizado en «(.+)»$/, (m, t) => `Updated in “${t(m[1])}”`],
  [/^(\d+) fila\(s\) quitadas de «(.+)»$/, (m, t) => `${m[1]} row(s) removed from “${t(m[2])}”`],
  [/^«(.+)» regenerad[ao]s? desde el proyecto$/, (m, t) => `“${t(m[1])}” regenerated from the project`],
  [/^(.+) regenerad[ao]s?$/, (m, t) => { const r = t(m[1]); return r !== m[1] ? `${r} regenerated` : null; }],
];

/* ---------------- claves que dependen del lugar ---------------- */
export const CONTEXTOS = [
  // tarjetas de «Mi plan» y de la pantalla de actualización: nombres de los planes
  { sel: ".plan-app h3", dic: { "Equipo":"Team", "Empresa":"Enterprise", "Prueba":"Trial", "Profesional":"Professional" } },
  // vistas del visor 3D («Planta» puede ser el nombre de la unidad del proyecto: solo se traduce aquí)
  { sel: ".v3d-barra", dic: { "Frente":"Front", "Lateral":"Side", "Planta":"Top", "Posterior":"Rear" } },
  // encabezado de la tabla de formatos estándar
  { sel: "th", dic: { "Base":"Basis" } },
];
